typedef int  (*pVUserIrqCB_t)    (int);
typedef int  (*pPyIrqCB_t)       (int, int);
typedef int  (*pVUserCB_t)       (int);

typedef struct {
    uint32_t eventPtr;
    uint32_t eventPopPtr;
    uint32_t eventQueue [MAX_QUEUED_VEC_IRQ];
} vecIrqState_t;

